# ruff: noqa
import pathlib
import re
import tkinter as tk
from tkinter import ttk
import xmltodict
import os
from pathlib import Path
from tkinter import filedialog
from PIL import Image, ImageTk
from ..utils.scfc_migrator import AcgScfcMigrator
from auto_config.generator.generator import generate_scfc
from ttkthemes import ThemedTk
from ..utils.coco_config_creator import generate_coco_file, create_coco_yaml_for_2enb
from ..utils.epc_reader import LuaExeption, LuaLibExeption


class Controller(ThemedTk):
    PROFILES_PATH = Path(os.path.abspath(__file__)).parents[2] / "config" / "profiles"
    PDDB_PATH = Path('/opt/emssim/pddb/')
    HOME_PATH = pathlib.Path.home()

    def __init__(self, *args, **kwargs):
        super().__init__(*args, theme="adapta", **kwargs)
        self.withdraw()
        self.deiconify()
        self.title("ACG Config Migrator")
        self.geometry('513x600')
        self.configure(bg='white')
        self.available_profiles = self.get_tl_list(self.PROFILES_PATH)
        self.graphics = self.__get_graphics()
        self.resizable(0, 0)
        self.option_add('*Dialog.msg.font', 'Helvetica 11')
        self.view()
        # setup_logger()

    def run(self):
        self.mainloop()

    def get_tl_list(self, profiles_path):
        return list(filter(lambda x: 'cloud_ho' not in x and 'MOON' not in x,
                           sorted(os.listdir(profiles_path))))

    # flake8: noqa: C901
    def view(self):
        header_frame = ttk.Frame(self)
        app_name = tk.Label(
            header_frame, text="ACG CM", bg="#00A0B5", fg="white", anchor=tk.W,
            font=('Comic Sans MS', 17, 'bold italic'), padx=320, name="app_name")
        app_name.pack(ipady=2, fill=tk.BOTH, side="right")
        cus_logo = ttk.Label(header_frame, image=self.graphics['logo_cus'], width=185, background="#00A0B5",
                             anchor=tk.E, name="logo_cus")
        cus_logo.pack(ipadx=5, ipady=5, side="left", fill=tk.BOTH, expand=True)
        select_profile_label = ttk.Label(self, text="Select topology", font=('Helvetica', 12, 'bold'),
                                         name='select_topology_label')
        select_profile_combobox = ttk.Combobox(self, values=self.available_profiles, width=29,
                                               name="select_profile_combobox")
        select_enb1_scfc_label = ttk.Label(self, text="Select eNB 1 xml file", font=('Helvetica', 12, 'bold'),
                                           name='select_enb1_scfc_label')
        select_enb1_scfc_file_explorer_button = ttk.Button(self, text="S", command=lambda: browse_file_enb1(), width=3,
                                                           image=self.graphics['folder_icon'])
        scfc_enb1_path_label = tk.Text(self, wrap="word", height=2, width=55)

        select_enb2_scfc_label = ttk.Label(self, text="Select eNB 2 xml file", font=('Helvetica', 12, 'bold'),
                                           name='select_enb2_scfc_label')
        select_enb2_scfc_file_explorer_button = ttk.Button(self, text="S", command=lambda: browse_file_enb2(), width=3,
                                                           image=self.graphics['folder_icon'])

        scfc_enb2_path_label = tk.Text(self, wrap="word", height=2, width=55)

        select_lua_label = ttk.Label(self, text="Select lua file", font=('Helvetica', 12, 'bold'),
                                     name='select_lua_label')
        select_lua_file_explorer_button = ttk.Button(self, text="S", command=lambda: browse_file_lua(), width=3,
                                                     image=self.graphics['folder_icon'])
        lua_path_label = tk.Text(self, wrap="word", height=2, width=55)

        migrate_button = tk.Button(self, text="Migrate config", command=lambda: migrate_config(), bg="#00B1CC",
                                   relief="raised", width=15, height=2, font=('Helvetica', 12), name='migrate_button')
        info_label = ttk.Label(self, text='', wraplength=480, font=('Helvetica', 12), name='info_label')

        def browse_file_enb1():
            file_path_enb1 = tk.filedialog.askopenfilename(initialdir=self.HOME_PATH)
            # / 'MN' / 'UTE' / 'robotlte' / 'testsuite' / 'WMP'
            scfc_enb1_path_label.delete(1.0, tk.END)
            scfc_enb1_path_label.insert(tk.INSERT, file_path_enb1)

        def browse_file_enb2():
            file_path_enb2 = tk.filedialog.askopenfilename(initialdir=self.HOME_PATH)
            scfc_enb2_path_label.delete(1.0, tk.END)
            scfc_enb2_path_label.insert(tk.INSERT, file_path_enb2)

        def browse_file_lua():
            file_path_lua = tk.filedialog.askopenfilename(initialdir=self.HOME_PATH)
            lua_path_label.delete(1.0, tk.END)
            lua_path_label.insert(tk.INSERT, file_path_lua)

        def migrate_config():
            enb1_path = scfc_enb1_path_label.get('1.0', tk.END).strip()
            enb2_path = scfc_enb2_path_label.get('1.0', tk.END).strip()
            lua_path = lua_path_label.get('1.0', tk.END).strip()
            selected_topology = select_profile_combobox.get()
            temp_config_file_dir = self.HOME_PATH / 'acg_cm_config'
            is_correct_topology = self.compare_enb_number(selected_topology, enb1_path, enb2_path)
            is_file_exist = self.check_is_file_exist(enb1_path, enb2_path)
            is_correct_file_type = self.is_correct_file_type(enb1_path)
            only_scfc = True

            if selected_topology and is_correct_file_type and is_correct_topology and is_file_exist:
                fsm_type = self.get_fsm_type(selected_topology)
                coco_from_enb1_path = self.HOME_PATH / 'output_config_migrator' \
                                      / f'{Path(enb1_path).name.rstrip(".xml")}_COCO.yaml'
                mrbts_nr, build_number = self.get_mrbts_nr_and_build_version(enb1_path)
                self._clear_old_config_files(temp_config_file_dir)
                generate_scfc(
                    build=build_number,
                    profile=selected_topology,
                    device_type=fsm_type,
                    output_dir=temp_config_file_dir
                )
                enb1_golden_name = [path for path in os.listdir(temp_config_file_dir) if
                                    re.search(r'\d+', mrbts_nr).group() == re.search(r'TL(\d+)', path).group(1)]
                enb1_golden_path = temp_config_file_dir / enb1_golden_name[0]
                migrator = AcgScfcMigrator(enb1_golden_path, enb1_path)
                # mozna przekazac sciezke do zapisu
                migrator.migrate_scfc()
                if self.check_is_lua_exist(lua_path):
                    try:
                        only_scfc = False
                        generate_coco_file(lua_path,
                                           enb1_path,
                                           coco_from_enb1_path,
                                           selected_topology)
                    except LuaExeption:
                        info_label.config(text="Cannot generate coco.yaml, lua probably contains functions")
                    except LuaLibExeption:
                        info_label.config(text="Lua lib is not installed. Run sudo apt-get install lua5.1")
                    else:
                        info_label.config(text="Migrated files saved in /home/ute/output_config_migrator/")

                if enb2_path and self.is_correct_file_type(enb2_path):
                    coco_from_enb2_path = temp_config_file_dir / 'COCO_from_enb2.yaml'
                    mrbts_nr, build_version = self.get_mrbts_nr_and_build_version(enb2_path)
                    enb2_golden_name = [path for path in os.listdir(temp_config_file_dir) if
                                        re.search(r'\d+', mrbts_nr).group() == re.search(r'TL(\d+)', path).group(1)]
                    enb2_golden_path = temp_config_file_dir / enb2_golden_name[0]
                    migrator = AcgScfcMigrator(enb2_golden_path, enb2_path)
                    migrator.migrate_scfc()
                    if self.check_is_lua_exist(lua_path):
                        generate_coco_file(lua_path,
                                           enb2_path,
                                           coco_from_enb2_path,
                                           selected_topology)
                        create_coco_yaml_for_2enb(coco_from_enb1_path,
                                                  coco_from_enb2_path)
                if only_scfc:
                    info_label.config(text="Migrated SCFC saved in /home/ute/output_config_migrator/")

            elif selected_topology and not enb1_path:
                info_label.config(text="Select eNB config xml file!")
            elif not selected_topology and enb1_path:
                info_label.config(text="Select topology!")
            elif not selected_topology and not enb1_path:
                info_label.config(text="Select topology and eNB config xml file!")

        header_frame.grid(column=0, row=0, columnspan=2)
        select_profile_label.grid(column=0, row=1, padx=(10, 0), pady=12, sticky=tk.W, columnspan=2)
        select_profile_combobox.grid(column=0, row=2, padx=(12, 0), pady=7, sticky=tk.W, columnspan=2)

        select_enb1_scfc_label.grid(column=0, row=3, padx=(10, 0), pady=7, sticky=tk.W, columnspan=2)
        select_enb1_scfc_file_explorer_button.grid(column=0, row=4, padx=(10, 0), pady=7, sticky=tk.W)
        scfc_enb1_path_label.grid(column=1, row=4, padx=(0, 315), pady=7, sticky=tk.W)

        select_enb2_scfc_label.grid(column=0, row=5, padx=(10, 0), pady=7, sticky=tk.W, columnspan=2)
        select_enb2_scfc_file_explorer_button.grid(column=0, row=6, padx=(10, 4), pady=7, sticky=tk.W)
        scfc_enb2_path_label.grid(column=1, row=6, pady=7, sticky=tk.W)

        select_lua_label.grid(column=0, row=7, padx=(10, 0), pady=7, sticky=tk.W, columnspan=2)
        select_lua_file_explorer_button.grid(column=0, row=8, padx=(10, 4), pady=7, sticky=tk.W)
        lua_path_label.grid(column=1, row=8, pady=7, sticky=tk.W)

        migrate_button.grid(column=0, row=9, padx=(0, 300), pady=19, columnspan=2)
        info_label.grid(column=0, row=10, padx=(0, 295), columnspan=2)

    def __get_graphics(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        folder_icon_resized = Image.open(graphic_src_path / "folder.png").resize((20, 20))
        logo_cus_resized = Image.open(graphic_src_path / "CUS_logo.png").resize((63, 33))

        folder_icon = ImageTk.PhotoImage(folder_icon_resized, master=self)
        logo_cus = ImageTk.PhotoImage(logo_cus_resized, master=self)

        return {'folder_icon': folder_icon, 'logo_cus': logo_cus}

    def _clear_old_config_files(self, temp_config_file_dir):
        if os.path.isdir(temp_config_file_dir):
            old_files = os.listdir(temp_config_file_dir)
            for file in old_files:
                os.remove(os.path.join(temp_config_file_dir, file))
            print("Clear old config files")

    def get_mrbts_nr_and_build_version(self, enb1_path):
        mrbts_nr = ''
        with open(enb1_path) as fd:
            file = xmltodict.parse(fd.read())
        for mo in file['raml']['cmData']['managedObject']:
            if ':MRBTS' in mo['@class']:
                mrbts_nr = mo['@distName']
                version = re.search(r'^([^_]+)', mo['@version']).group(1)
        pddb_file_list = [
            f for f in os.listdir(self.PDDB_PATH) if
            os.path.isfile(os.path.join(self.PDDB_PATH, f)) and f.endswith('.txt')
        ]
        selected_version_build_list = [build for build in pddb_file_list if version in build]
        if not selected_version_build_list:
            selected_version_build_list.append("SBTS23R4")
        return mrbts_nr, selected_version_build_list[-1]

    def compare_enb_number(self, topology, enb1_path, enb2_path):
        enb_num = 1
        selected_path_list = [path for path in [enb1_path, enb2_path] if path != '']
        found_enb_num = re.search(r'CLOUD_(\d+)', topology)
        if found_enb_num:
            enb_num = found_enb_num.group(1)
        if len(selected_path_list) == int(enb_num):
            return True
        else:
            if enb_num == 1:
                self.children['info_label'].config(text="You select two files but selected topology has one eNB")
            else:
                self.children['info_label'].config(text="You select one file but selected topology has two eNBs")
            return False

    def is_correct_file_type(self, scfc_path):
        if scfc_path.lower().endswith('.xml'):
            return True
        else:
            self.children['info_label'].config(text="Selected file is not in XML format")
            return False

    def get_golden_file_path(self, topology):
        profiles_path = Path(os.path.abspath(__file__)).parents[3] / "test" / "config_ref"
        directory = [directory for directory in os.listdir(profiles_path) if
                     topology == re.search(r'config_out-(.*)', directory).group(1)]
        golden_scfc_directory = str(profiles_path) + f"/{directory[0]}/"
        golden_scfc_lsit = [golden_scfc_directory +
                            scfc_path for scfc_path in os.listdir(str(profiles_path) +
                                                                  f"/{directory[0]}/") if "GOLDEN" in scfc_path]
        return golden_scfc_lsit

    def check_is_lua_exist(self, lua_path):
        lua_path_exist = os.path.exists(lua_path) if lua_path != '' else False
        if not lua_path_exist:
            if lua_path != '':
                self.children['info_label'].config(text="Selected lua file doesn't exist")
        else:
            return True

    def check_is_file_exist(self, enb1_path, enb2_path):
        enb1_file_exist = os.path.exists(enb1_path)
        enb2_file_exist = os.path.exists(enb2_path) if enb2_path != '' else True

        if not enb1_file_exist:
            self.children['info_label'].config(text="Selected file for eNB 1 doesn't exist")
        if not enb2_file_exist:
            self.children['info_label'].config(text="Selected file for eNB 2 doesn't exist")
        if enb1_file_exist and enb2_file_exist:
            return True

